package org.eclipse.rdf4j.federated;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotSame;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.List;
import java.util.Set;

import org.eclipse.rdf4j.federated.algebra.EmptyStatementPattern;
import org.eclipse.rdf4j.federated.algebra.NUnion;
import org.eclipse.rdf4j.federated.algebra.TrueStatementPattern;
import org.eclipse.rdf4j.federated.structures.QueryInfo;
import org.eclipse.rdf4j.model.util.Values;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.Var;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

class FedXOperatorMetadataTest {

	@Test
	void unionOnlyAssuresNamesProducedByEveryBranch() {
		var union = new NUnion(List.of(pattern("x", "p", "o"), pattern("x", "p", "other")),
				Mockito.mock(QueryInfo.class));

		assertEquals(Set.of("x", "p"), union.getAssuredBindingNames());
	}

	@Test
	void nestedUnionsIntersectGuaranteesAtEveryLevel() {
		var nested = new NUnion(List.of(
				new NUnion(List.of(pattern("x", "p", "left"), pattern("x", "q", "middle")),
						Mockito.mock(QueryInfo.class)),
				pattern("x", "p", "right")), Mockito.mock(QueryInfo.class));

		assertEquals(Set.of("x"), nested.getAssuredBindingNames());
	}

	@Test
	void singleBranchAndEmptyUnionsHaveStableAssuredNames() {
		assertEquals(Set.of("x", "p", "o"),
				new NUnion(List.of(pattern("x", "p", "o")), Mockito.mock(QueryInfo.class))
						.getAssuredBindingNames());
		assertTrue(new NUnion(List.of(), Mockito.mock(QueryInfo.class)).getAssuredBindingNames().isEmpty());
	}

	@Test
	void emptyBranchesDoNotRemoveNamesGuaranteedByLiveBranches() {
		var union = new NUnion(List.of(
				new EmptyStatementPattern(pattern("x", "p", "unreachable")), pattern("x", "p", "o")),
				Mockito.mock(QueryInfo.class));

		assertEquals(Set.of("x", "p", "o"), union.getAssuredBindingNames());
	}

	@Test
	void allEmptyUnionBranchesHaveNoAssuredNames() {
		var union = new NUnion(List.of(new EmptyStatementPattern(pattern("x", "p", "left")),
				new EmptyStatementPattern(pattern("x", "p", "right"))), Mockito.mock(QueryInfo.class));

		assertTrue(union.getAssuredBindingNames().isEmpty());
	}

	@Test
	void trueStatementPatternOwnsClonedVarsAndPreservesNamedContext() {
		StatementPattern source = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS,
				Var.of("s", Values.iri("urn:s")), Var.of("p", Values.iri("urn:p")),
				Var.of("o", Values.literal("value")), Var.of("g", Values.iri("urn:graph")));

		TrueStatementPattern pattern = new TrueStatementPattern(source);

		assertEquals(StatementPattern.Scope.NAMED_CONTEXTS, pattern.getScope());
		assertNotSame(source.getSubjectVar(), pattern.getSubjectVar());
		assertNotSame(source.getPredicateVar(), pattern.getPredicateVar());
		assertNotSame(source.getObjectVar(), pattern.getObjectVar());
		assertNotSame(source.getContextVar(), pattern.getContextVar());
		assertSame(source, source.getSubjectVar().getParentNode());
		assertSame(source, source.getContextVar().getParentNode());
		assertSame(pattern, pattern.getSubjectVar().getParentNode());
		assertSame(pattern, pattern.getContextVar().getParentNode());
		assertEquals("urn:graph", pattern.getContextVar().getValue().stringValue());

		StatementPattern clone = pattern.clone();
		assertEquals(StatementPattern.Scope.NAMED_CONTEXTS, clone.getScope());
		assertEquals("urn:graph", clone.getContextVar().getValue().stringValue());
		assertNotSame(pattern.getContextVar(), clone.getContextVar());
		assertSame(clone, clone.getContextVar().getParentNode());
		assertSame(pattern, pattern.getContextVar().getParentNode());
	}

	private static StatementPattern pattern(String subject, String predicate, String object) {
		return new StatementPattern(Var.of(subject), Var.of(predicate), Var.of(object));
	}
}
